"""Exact reviewed presentation edits; reversal is a comparison, not identity claim."""
SEGMENTS=[{'old': 'def main(diagnostic=None,continuous=False,continuous_version=23):\n', 'new': 'def main(diagnostic=None,continuous=False,continuous_version=23,visual=None):\n'}, {'old': '    gpu=gpu_gate(args.gpu)\n', 'new': '    gpu=gpu_gate(args.gpu) if visual is None else visual.gpu_binding()\n'}, {'old': "    from device_binding import install as bind_assigned_renderer\n    render_assignment=bind_assigned_renderer(sapien,gpu['pci_bus_id'])\n    import imageio.v2 as imageio\n", 'new': "    if visual is None:\n        from device_binding import install as bind_assigned_renderer\n        render_assignment=bind_assigned_renderer(sapien,gpu['pci_bus_id'])\n        import imageio.v2 as imageio\n    else:render_assignment=visual.render_binding()\n"}, {'old': "    base=release/'workspace/base';candidate=release/'workspace/candidate'\n", 'new': "    base=release/'workspace/base';candidate=release/'workspace/candidate'\n    if visual is not None:visual.install(sapien,base,pair_probe,cfg)\n"}, {'old': '            sapien.render.set_ray_tracing_samples_per_pixel(4)\n', 'new': '            if visual is None:sapien.render.set_ray_tracing_samples_per_pixel(4)\n'}, {'old': "                raise RuntimeError('continuation_shadow_not_independent')\n", 'new': "                raise RuntimeError('continuation_shadow_not_independent')\n    if visual is not None:\n        visual.bind('formal',env)\n        if cfg.mode!='layout':\n            visual.bind('grasp_preview',grasp_scene);visual.bind('separation_preview',separation_scene)\n            if pair_probe:visual.bind('continuation_preview',continuation_scene)\n"}, {'old': "        log=(out/'events.jsonl').open('x');writer=imageio.get_writer(str(out/'episode.mp4'),fps=10)\n", 'new': "        log=(out/'events.jsonl').open('x');writer=imageio.get_writer(str(out/'episode.mp4'),fps=10) if visual is None else visual.writer(out)\n"}, {'old': '        if preview_mode or (not force and step%25):return\n', 'new': '        if preview_mode:return\n        if visual is not None:visual.capture(env,step,phase,held_id,drive is not None,force)\n        if not force and step%25:return\n'}, {'old': "        if not preview_mode and step%25==0:writer.append_data(env.get_obs()['observation']['head_camera']['rgb'])\n", 'new': "        if not preview_mode and step%25==0:\n            if visual is None:writer.append_data(env.get_obs()['observation']['head_camera']['rgb'])\n            else:visual.picture_checkpoint(env,step)\n"}, {'old': "        development_llm=dict(instrumented=False,usage=None,source='parent turn.completed pending'))\n", 'new': "        development_llm=dict(instrumented=False,usage=None,source='parent turn.completed pending'))\n    if visual is not None:manifest['headless_candidate']=visual.manifest(identity,config)\n"}, {'old': '        return check_source_unchanged\n', 'new': "        return check_source_unchanged\n    if visual is not None and visual.admission:\n        if not validation['valid']:raise RuntimeError('invalid_generated_or_original_layout:'+str(validation['errors']))\n        status=visual.admit(copy_to_shadow,state)\n        writer.close();log.close();trace.close()\n        return status\n"}, {'old': '            initialization_physics_steps=None,\n', 'new': '            initialization_physics_steps=None if visual is None else visual.initialization_steps(),\n'}, {'old': '            preview=dict(fps=10,capture_every_steps=25,ray_samples=4),\n', 'new': '            preview=dict(fps=10,capture_every_steps=25,ray_samples=4) if visual is None else visual.capture_contract(),\n'}, {'old': "            claim='diagnostic prototype; not the frozen historical verifier')\n", 'new': "            claim='diagnostic prototype; not the frozen historical verifier')\n        if visual is not None:result['headless_candidate']=visual.final_accounting(step,preview_total_steps)\n"}]

def remove_headless(text):
    for delta in reversed(SEGMENTS):
        assert text.count(delta["new"])==1,delta["new"][:100]
        text=text.replace(delta["new"],delta["old"],1)
    return text
